// Extraer parámetros de búsqueda del body o query
const inputData = $input.first().json;
const body = inputData.body || {};
const query = inputData.query || {};

const params = {
  codigo: (body.codigo || query.codigo || '').toString().trim().toUpperCase(),
  talla: body.talla || query.talla || null,
  color: (body.color || query.color || '').toString().trim().toLowerCase(),
  nombre: (body.nombre || query.nombre || '').toString().trim().toLowerCase(),
  incluir_precio_interno: body.incluir_precio_interno === true || body.incluir_precio_interno === 'true' || query.incluir_precio_interno === 'true'
};

return [{ json: { params } }];

// Obtener filtros ingresados y datos retornados por Supabase
const params = $('Preparar Filtros').first().json.params;
const items = $input.all().map(i => i.json);

// Aplicar filtros opcionales en memoria
let filtrados = items.filter(item => {
  const prod = item.productos || {};

  // Filtro por código de modelo o SKU
  if (params.codigo) {
    const matchCodigo = (prod.codigo_modelo || '').toUpperCase().includes(params.codigo);
    const matchSku = (item.sku_variante || '').toUpperCase().includes(params.codigo);
    if (!matchCodigo && !matchSku) return false;
  }

  // Filtro por talla
  if (params.talla) {
    if (Number(item.talla) !== Number(params.talla)) return false;
  }

  // Filtro por color
  if (params.color) {
    const matchColor = (item.color || '').toLowerCase().includes(params.color);
    if (!matchColor) return false;
  }

  // Filtro por nombre fantasía
  if (params.nombre) {
    const matchNombre = (prod.nombre_fantasia || '').toLowerCase().includes(params.nombre);
    if (!matchNombre) return false;
  }

  return true;
});

// Formatear la salida según las reglas de negocio
const catalogoFormateado = filtrados.map(item => {
  const prod = item.productos || {};
  const registro = {
    variante_id: item.id,
    producto_id: item.producto_id,
    codigo_modelo: prod.codigo_modelo,
    nombre_fantasia: prod.nombre_fantasia,
    sku: item.sku_variante,
    color: item.color,
    talla: item.talla,
    stock_disponible: item.stock_disponible,
    material: prod.material,
    taco_base: prod.taco_base,
    horma: prod.horma,
    info_adicional: prod.info_adicional,
    imagen_url: item.imagen_portada_variante || prod.imagen_defecto_url || null,
    precio_vendedores: Number(item.precio_vendedores)
  };

  // Regla: precio_interno solo si incluir_precio_interno es true
  if (params.incluir_precio_interno) {
    registro.precio_interno = Number(item.precio_interno);
  }

  return registro;
});

return [{
  json: {
    success: true,
    total_disponibles: catalogoFormateado.length,
    filtros_aplicados: params,
    productos: catalogoFormateado
  }
}];
